import pandas as pd,numpy as np
from pymatgen.core import Structure
D=pd.read_csv('nlo_pool.csv')
ions={'Li','Na','K','Rb','Cs','Be','Mg','Ca','Sr','Ba','Sc','Y','Tl'}
neg={'O','S','Se','Te','N','P','As','C','F','Cl','Br','I'}
for _,r in D.iterrows():
 s=Structure.from_str(r.poscar,fmt='poscar'); els=set(x.specie.symbol for x in s)
 # species which serve as anions in this compound
 ani=els&neg
 if len(ani)>1:
  if ani&{'S','Se','Te','O','Cl','Br','I'}: ani=ani-{'P','As'}
  if ani&{'S','Se'}: ani=ani-{'Te'}
 cov=els-ions-ani
 out=[];ts=[];wt=0
 for e in sorted(cov):
  t=np.zeros((3,3)); w=0
  for p in s:
   if p.specie.symbol!=e:continue
   ne=sorted([x for x in s.get_neighbors(p,4.0) if x.specie.symbol in ani],key=lambda x:x.nn_distance)
   if not ne:continue
   ne=[x for x in ne if x.nn_distance<ne[0].nn_distance*1.18]
   for x in ne:
    d=x.nn_distance; v=(x.coords-p.coords)/d
    t+=np.outer(v,v)*d**3; w+=d**3
  if w:
   ts.append(t);wt+=w
   eig=np.linalg.eigvalsh(t/w)
   out.append(e+':'+','.join(f'{x:.3f}' for x in eig))
 if wt:
  eig=np.linalg.eigvalsh(np.sum(ts,axis=0)/wt)
  spread=eig[-1]-eig[0]
 else:spread=0
 print(r.candidate_id,'A='+f'{spread:.4f}', ' '.join(out))
